            { eng: "Prepare", jpn: "準備する", exEng: "We must prepare for the journey.", exJpn: "私たちは旅の準備をしなければなりません。" },
            { eng: "Relax", jpn: "リラックスする", exEng: "I want to relax on the beach.", exJpn: "私はビーチでリラックスしたいです。" },
            { eng: "Enjoy", jpn: "楽しむ", exEng: "Did you enjoy your holiday?", exJpn: "休日は楽しみましたか？" },
            { eng: "Recommend", jpn: "お勧めする", exEng: "I highly recommend this city.", exJpn: "この都市を強くお勧めします。" },
            { eng: "Reason", jpn: "理由", exEng: "What is the reason you went there?", exJpn: "あなたがそこに行った理由は何ですか？" }
